function Say($text, $color = "White") { Write-Host $text -ForegroundColor $color }

# ---------- 1. Project folder dhundho ----------
$Root = $PSScriptRoot
if (-not $Root) { $Root = (Get-Location).Path }

if (-not (Test-Path (Join-Path $Root "package.json"))) {
    $here = (Get-Location).Path
    if (Test-Path (Join-Path $here "package.json")) {
        $Root = $here
    } else {
        Say ""
        Say "GALTI: package.json nahi mila." Red
        Say "Is script ko apne 'crm' project folder (jisme package.json hai) me rakh kar chalayein." Yellow
        exit 1
    }
}

if (Test-Path (Join-Path $Root "src\app")) {
    $AppDir = Join-Path $Root "src\app"
} elseif (Test-Path (Join-Path $Root "app")) {
    $AppDir = Join-Path $Root "app"
} else {
    Say "GALTI: 'app' ya 'src\app' folder nahi mila. Kya yeh Next.js project hai?" Red
    exit 1
}


$Stamp = Get-Date -Format "yyyy-MM-dd_HH-mm-ss"
$BackupDir = Join-Path $Root ("_backups\" + $Stamp)
$Utf8NoBom = New-Object System.Text.UTF8Encoding($false)
$Updated = @()
$Created = @()
$Skipped = @()

Say ""
Say "Project folder : $Root" Cyan
