# ---------- 2. Helper: backup + write ----------
function Write-ProjectFile([string]$Target, [string]$Base64) {
    # [System.IO] use karte hain taaki [phone] / [slug] jaise folder naam theek se chalein
    $bytes = [Convert]::FromBase64String($Base64)
    $rel = $Target.Substring($Root.Length).TrimStart("\")

    if ([System.IO.File]::Exists($Target)) {
        $backupPath = Join-Path $BackupDir $rel
        [void][System.IO.Directory]::CreateDirectory([System.IO.Path]::GetDirectoryName($backupPath))
        [System.IO.File]::Copy($Target, $backupPath, $true)
        $script:Updated += $rel
        Say "  UPDATE  $rel" Green
    } else {
        $script:Created += $rel
        Say "  NEW     $rel" Yellow
    }

    [void][System.IO.Directory]::CreateDirectory([System.IO.Path]::GetDirectoryName($Target))
    [System.IO.File]::WriteAllBytes($Target, $bytes)
}

# Sirf asli code folders me dhundho: app\ aur components\
# (backup / disabled / temp folders ko kabhi nahi chhedte)
function Find-ProjectFiles([string]$Name) {
    $searchRoots = @($AppDir)
    foreach ($c in @((Join-Path $Root "components"), (Join-Path $Root "src\components"))) {
        if ((Test-Path $c) -and ($searchRoots -notcontains $c)) { $searchRoots += $c }
    }
    $skipPattern = '\\(node_modules|\.next|_backups|\.git)\\|(?i)backup|disabled|[-_]temp|rider-step2-6-fix|live-source'
    $results = @()
    foreach ($r in $searchRoots) {
        $results += Get-ChildItem -LiteralPath $r -Recurse -File -Filter $Name -ErrorAction SilentlyContinue |
            Where-Object { $_.FullName.Substring($Root.Length) -notmatch $skipPattern }
    }
    return $results
}

