# --- Database: nayi tables (AppSetting, CustomerAccount) ---
# Ab yeh tables app khud pehli baar use hone par bana leta hai (prisma generate ki zaroorat nahi).
# schema.prisma me models sirf record ke liye add kiye jaate hain.
$SchemaPath = Join-Path $Root "prisma\schema.prisma"
if (Test-Path $SchemaPath) {
    $schemaText = Get-Content -LiteralPath $SchemaPath -Raw
    if ($schemaText -notmatch "model\s+AppSetting\s*\{" -or $schemaText -notmatch "model\s+CustomerAccount\s*\{") {
        $bk = Join-Path $BackupDir "prisma\schema.prisma"
        New-Item -ItemType Directory -Force -Path (Split-Path $bk) | Out-Null
        Copy-Item -LiteralPath $SchemaPath -Destination $bk -Force
        $add = $Utf8NoBom.GetString([Convert]::FromBase64String(($B64_SCHEMA_ADD -join "")))
        [System.IO.File]::WriteAllText($SchemaPath, $schemaText.TrimEnd() + "`r`n" + $add, $Utf8NoBom)
        Say "  UPDATE  prisma\schema.prisma (AppSetting, CustomerAccount)" Green
    }
}
Say "  OK      Settings + Customer tables pehli baar page khulte hi apne aap ban jayengi" Green

